        '重新整理頁面就會更新到最新版。': 'Reload the page to get the latest version.',
        // v6.39.0 完整智能體模式
        '：好感': ': affinity',
        '、信任': ', trust',
        '季節': 'Season',
        '公庫銀幣': 'treasury silver',
        '全鎮平均心情': 'average town mood',
