        '不用花公庫的錢': 'no treasury cost',
        '在乎': 'values',
        '最近記得': 'recently remembers',
        '你是模擬小鎮的村民決策引擎。鎮上有人提了一個提案，請替下面每位村民決定投贊成或反對，並用他自己的口吻給一句理由（20 字內）。要依每個人的性格、在乎的價值、跟提案人的交情、最近的記憶與鎮況判斷，不要全部一致。': 'You are the villager decision engine of a town simulation. Someone has raised a proposal. For each villager below decide whether they vote for or against and give a one-line reason in their own voice (under 15 words). Judge by each person\'s traits, values, relationship with the proposer, recent memories and the state of the town; they should not all agree.',
        '【鎮況】': '[Town] ',
        '【提案】': '[Proposal] ',
        '提案人': 'proposer',
        '【村民】': '[Villagers]',
        '只輸出 JSON 陣列，每個元素 {"n":序號,"vote":"for"或"against","why":"理由"}，不要其他文字。': 'Output only a JSON array, each element {"n":index,"vote":"for" or "against","why":"reason"}, nothing else.',
        '你正在扮演鎮長「': 'You are playing the mayor "',
        '」（': '" (',
        '歲；性格': 'y; traits',
        '）。全鎮對一個提案投完票了，現在由你裁決。': '). The town has voted on a proposal and the ruling is yours.',
        '【票數】': '[Votes] ',
        '依你的性格、價值觀、跟提案人的交情、公庫狀況與票數決定：approve（批准）、reject（否決）或 shelve（先擱置幾天）。只輸出 JSON：{"action":"approve|reject|shelve","why":"一句話理由（25 字內，第一人稱）"}': 'Decide by your traits, values, relationship with the proposer, the treasury and the vote: approve, reject or shelve (set aside for a few days). Output only JSON: {"action":"approve|reject|shelve","why":"one-line reason (under 20 words, first person)"}',
        '）。今天鎮上輪到你可以向大家提一個提案。': '). Today it is your turn to raise a proposal to the town.',
        '【你想得到的幾個點子】': '[Ideas you can think of]',
        '依你的身分與處境決定：挑一個最想提的（回序號），或者今天不提（回 0）。只輸出 JSON：{"choice":序號或0,"pitch":"你向全鎮說明的一兩句話（第一人稱，50 字內）"}': 'Decide by who you are and your situation: pick the one you most want to raise (answer its index), or raise nothing today (answer 0). Output only JSON: {"choice":index or 0,"pitch":"one or two sentences pitching it to the town (first person, under 40 words)"}',
        '🤔 {who}想了想，今天沒什麼要跟大家提的。': '🤔 {who} thought about it and has nothing to propose today.',
        '完整智能體模式': 'Full agent mode',
        '（自備金鑰，預設開）': '(own key: on by default)',
        '（小鎮內建 AI，預設關）': '(built-in AI: off by default)',
        '開啟後，村民投票、要不要提案與提什麼、鎮長批准與否，都由 AI 依各自的記憶、性格、交情與鎮況推理並附理由；規則版只在 AI 失敗時墊底。每件提案約多 2～4 次 AI 呼叫、每天多 1 次。': 'When on, villagers\' votes, whether and what to propose, and the mayor\'s ruling are all reasoned by the AI from each villager\'s memories, personality, relationships and the state of the town, with a stated reason; the rule-based version only steps in when the AI fails. Roughly 2–4 extra AI calls per proposal plus one per day.',
        '走小鎮內建 AI 的話，每日 100 則很快就會用完；建議搭配自備金鑰。': 'On the built-in town AI the daily 100 messages run out fast; pair it with your own key.',
        '這件案子的投票／裁決由 AI 依記憶與性格推理': 'The votes / ruling on this one were reasoned by the AI from memories and personality',
        // v6.38.0 事件卡（上帝視角）
        '冷卻中，還要 {n} 天': 'Cooling down, {n} more day(s)',
        '今天的兩張已經打完，明天再來': 'Both of today\'s cards are played; come back tomorrow',
        '這張卡現在打不出去': 'This card cannot be played right now',
        '事件卡': 'Event cards',
        '七天後': 'Seven days later',
        '今天還能打': 'Playable today',
        '你是上帝視角：不投錢、不下令，只能往小鎮丟事件，然後看村民怎麼反應、怎麼提案、鎮上怎麼變。點卡看說明，按「打出」才會發生；同一張打過要等冷卻。': 'You are the god\'s-eye observer: no money, no orders, only events thrown at the town. Then watch how the villagers react, what they propose and how the town changes. Tap a card for details; nothing happens until you press "Play". A played card needs to cool down.',
        '全部': 'All',
