        '收到失散多年的親人來信，去探親': 'went to visit a long-lost relative who wrote',
        '連日烈日，水井見底，田裡的作物發黃。': 'Days of blazing sun; the wells run dry and the crops turn yellow.',
        '天氣轉乾旱 3 天、食物 −15%、開啟「糧荒」考驗': 'Drought for 3 days, food −15%, starts the "Famine" trial',
        '狂風暴雨掀了屋瓦，工地的鷹架倒了一半。': 'Wind and rain tear off roof tiles; half the scaffolding collapses.',
        '天氣轉暴風雨 2 天、木材 −20、工程進度 −20%、全鎮心情 −5': 'Storm for 2 days, wood −20, construction progress −20%, town mood −5',
        '一夜之間氣溫驟降，柴火燒得比吃飯還快。': 'The temperature plunges overnight; firewood burns faster than food is eaten.',
        '天氣轉雪 3 天、食物 −10%、木材 −15、全鎮心情 −8': 'Snow for 3 days, food −10%, wood −15, town mood −8',
        '火災': 'Fire',
        '深夜一處倉房起火，半鎮的人提水救火到天亮。': 'A storehouse catches fire at night; half the town carries water until dawn.',
        '木材 −30%、食物 −10%、全鎮心情 −10；守衛與木匠印象最深': 'Wood −30%, food −10%, town mood −10; guards and carpenters take it hardest',
