        '工程進度 −40%、石材 −25、全鎮心情 −12': 'Construction progress −40%, stone −25, town mood −12',
        '河水漫過堤岸，低處的人家連夜搬到高地。': 'The river tops its banks; the low houses move to high ground overnight.',
        '天氣轉雨 3 天、食物 −10%、布料 −30%、兩人暫避他鄉 2 天': 'Rain for 3 days, food −10%, cloth −30%, two villagers shelter elsewhere for 2 days',
        '商隊被劫': 'Caravan robbed',
