        '銀幣 −20%、商人心情 −15、開啟「匪患」考驗': 'Silver −20%, traders\' mood −15, starts the "Bandits" trial',
        '流言': 'Rumour',
        '一句沒頭沒尾的話在井邊傳開，兩個人的名字被綁在一起。': 'A half-heard remark spreads at the well, tying two names together.',
        '隨機兩人好感 −25，容易引出調解提案': 'Two random villagers −25 affinity; tends to trigger mediation proposals',
