        '銀幣 −60、工具 −3、守衛心情 −8、一人被懷疑': 'Silver −60, tools −3, guards\' mood −8, one villager falls under suspicion',
        '公庫失竊，有人在背後說是我。我沒有。': 'The treasury was robbed and people whisper it was me. It wasn\'t.',
        '稅吏上門': 'Tax collector',
