        '外地商會聯手壓價，鎮上的貨賣不出好價錢。': 'Outside guilds collude to push prices down; town goods fetch nothing.',
        '開啟「商會壓價」考驗、銀幣 −10%': 'Starts the "Price war" trial, silver −10%',
        '鎮長醜聞': 'Mayor scandal',
