        '獵人說在山裡看見閃光的石頭，整鎮都在談。': 'A hunter saw glinting stones in the hills and the whole town is talking.',
        '發現一處新探索區、金屬 +10；容易引出探險提案': 'Discovers a new exploration zone, metal +10; tends to trigger expedition proposals',
        '神秘旅人': 'Mysterious traveller',
        '一個背著大包袱的人在客棧住下，說想在這裡安家。': 'A traveller with a huge pack takes a room at the inn and talks of settling down.',
        '一位新居民搬來': 'A new resident moves in',
        '失散親人來信': 'Letter from a lost relative',
        '郵差送來一封泛黃的信，署名是多年沒消息的人。': 'The post brings a yellowed letter signed by someone unheard of for years.',
        '一人心情 +10 並出門探親 4 天': 'One villager mood +10 and leaves to visit family for 4 days',
