        '買賣': 'Trade',
        '研究「{name}」': 'Research "{name}"',
        '{who}覺得鎮上該把{name}研究出來：{desc}（要累積 {cost} 點研究進度）。': '{who} thinks the town should research {name}: {desc} (needs {cost} research progress).',
        '進一批{item}備料': 'Stock up on {item}',
        '{item}快見底了，{who}提議從公庫撥 {n} 銀幣去商店進 {qty} 份。': '{item} is almost gone. {who} proposes spending {n} silver from the treasury to buy {qty} at the shop.',
        '把多出來的{item}賣掉': 'Sell the surplus {item}',
        '{item}堆了 {have} 份，放著也是壞掉。{who}提議賣掉 {qty} 份，大約能進帳 {n} 銀幣。': '{have} {item} are piling up and would only spoil. {who} proposes selling {qty} for roughly {n} silver.',
