        '{agentA}在{loc}送了{agentB}{gift}作為驚喜，{agentB2}{react}，兩人的感情更加深厚了。': '{agentA} surprised {agentB} with {gift} at {loc}; {agentB2} {react}, and their bond deepened.',
        '{agentA}在{loc}和{agentB}分享了{scene}的美景，話語間暗藏著告白的勇氣，{agentB2}{react}。': 'At {loc}, {agentA} shared {scene} with {agentB}, a confession hiding between the words; {agentB2} {react}.',
        // v6.19.0 B1 規則式對話摘要模板 key(scratchpad/summary_convert.js 產生)
        '{loc}裡，{agentA}讚美了{agentB}親手做的{food}，兩人甜蜜地打鬧著，笑聲讓路過的人都忍不住微笑。': 'At {loc}, {agentA} praised the {food} {agentB} made by hand, and the two teased each other sweetly, their laughter making passers-by smile.',
        '{j}因為看到{o}和別人說笑而醋意大發，兩人經歷了一場小風波，最終在{loc}和好。': '{j} got jealous after seeing {o} laughing with someone else. After a little storm, the two made up at {loc}.',
        '{season}的{loc}裡，{agentA}和{agentB}手牽手散步，分享著{scene}的浪漫景色，氣氛溫馨而甜蜜。': 'At {loc} in {season}, {agentA} and {agentB} strolled hand in hand, sharing {scene} in a warm, sweet mood.',
        '{agentA}和{agentB}在{loc}正面交鋒，針鋒相對的言語讓空氣彷彿凝結，周圍的居民紛紛側目。': '{agentA} and {agentB} clashed head-on at {loc}, their sharp words freezing the air as nearby residents turned to stare.',
        '{agentA}當面質問{agentB}散播流言蜚語的事，兩人在{loc}爆發了激烈口角，怒氣沖天，場面一度失控。': '{agentA} confronted {agentB} about spreading rumors, and the two exploded at {loc} in a furious shouting match that nearly got out of hand.',
        '{agentA}在{loc}試圖與{agentB}和解，但雙方仍帶著心結，氣氛雖有緩和卻依然充滿張力。': 'At {loc}, {agentA} tried to make peace with {agentB}, but both still held grudges; the air eased yet stayed tense.',
        '{agentA}幫{agentB}拿掉頭上的落葉時兩人靠得很近，{who}的臉頰微微泛紅，{loc}的空氣中瀰漫著微妙的心動氣息。': '{agentA} helped {agentB} remove a leaf from their hair, standing very close; {who}\'s cheeks flushed faintly, and {loc} filled with a subtle flutter of hearts.',
        '{agentA}興沖沖地在{loc}和摯友{agentB}分享了一個驚天八卦，兩人越聊越起勁，甚至約好了一起去探個究竟，氣氛既神秘又興奮。': '{agentA} excitedly shared some earth-shaking gossip with best friend {agentB} at {loc}; the more they talked the more excited they got, even agreeing to investigate together.',
        '{agentA}在{loc}向摯友{agentB}傾訴了最近的煩惱，{agentB2}耐心傾聽並貼心地準備了{food}，兩人之間的友誼更加堅定了。': 'At {loc}, {agentA} confided recent worries to best friend {agentB}; {agentB2} listened patiently and thoughtfully prepared {food}. Their friendship grew stronger.',
        '{agentA}和{agentB}在{loc}回憶起初來邊境鎮的趣事，笑淚交織之間，深厚的友情讓旁人都為之動容。': '{agentA} and {agentB} reminisced at {loc} about their first days in town, laughing and tearing up, a friendship so deep it moved onlookers.',
        '{agentA}在{loc}熱情地招呼了新來的{agentB}，推薦了鎮上的美食{food}，給{agentB2}留下了溫暖的第一印象。': 'At {loc}, {agentA} warmly greeted newcomer {agentB} and recommended the local {food}, leaving {agentB2} a warm first impression.',
        '{agentA}和{agentB}在{loc}初次交談，兩人相談甚歡，約好了改天再深入聊聊，邊境鎮又多了一段新的緣分。': '{agentA} and {agentB} hit it off at their first meeting at {loc} and agreed to talk more another day; the town gained a new connection.',
        '{agentA}和{agentB}在{loc}不小心撞在一起,尷尬又好笑地認識了彼此。': '{agentA} and {agentB} bumped into each other at {loc} and got acquainted in an awkward, funny way.',
        '{agentA}用一則八卦成功勾起{agentB}的興趣,兩人在{loc}越聊越起勁。': '{agentA} hooked {agentB}\'s interest with a bit of gossip, and the two got chatting at {loc}.',
        '{agentB}被{agentA}手上的{item}吸引,兩人就這麼聊開了,約好改天再見。': '{agentB} was drawn to {agentA}\'s {item}, and the two got talking, agreeing to meet again.',
        '{grump}嘴上潑冷水,卻還是對新認識的{other}伸出了援手,反差讓人莞爾。': '{grump} poured cold water with words but still offered a hand to new acquaintance {other}, a contrast that made people smile.',
        '{agentA}和{agentB}在{loc}一見如故,相談甚歡,彷彿認識了很久的老友。': '{agentA} and {agentB} hit it off instantly at {loc}, chatting like old friends.',
        '{agentA}興奮地和{agentB}分享了一個神奇的發現，兩人在{loc}聊得眉飛色舞，約好下次一起去探索。': '{agentA} excitedly told {agentB} a marvelous discovery, and the two chatted animatedly at {loc}, agreeing to explore together next time.',
        '{agentA}帶了{food}到{loc}和{agentB}邊吃邊聊，{season}的暖意讓兩人的對話格外愜意。': '{agentA} brought {food} to {loc} and chatted with {agentB} over it; the warmth of {season} made the conversation especially cozy.',
        '{agentA}在{loc}向{agentB}{sum}，兩人笑得前仰後合，{loc2}裡充滿了歡樂的氣氛。': 'At {loc}, {agentA} {sum} to {agentB}, and both doubled over laughing; {loc2} was filled with cheer.',
        '{agentA}在{loc}送了{agentB}{gift}作為感謝，{agentB2}感動之餘兩人的友誼又更進了一步，{season}的空氣裡充滿了溫暖。': 'At {loc}, {agentA} gave {agentB} {gift} as thanks; {agentB2} was touched and the friendship deepened, the {season} air full of warmth.',
        '{agentA}和{agentB}在{loc}低聲討論著鎮上的神秘傳聞，越聊越覺得事情不簡單，兩人的表情既好奇又緊張。': '{agentA} and {agentB} whispered at {loc} about the town\'s mysterious rumor, growing more convinced something was up, curious and nervous at once.',
        '{agentB}在{loc}發現了獨自落寞的{agentA}，溫柔地遞上一杯{food}，用真摯的話語驅散了陰霾，{agentA2}眼眶泛紅地笑了。': 'At {loc}, {agentB} found a downcast {agentA}, gently handed over a cup of {food}, and chased the gloom away with sincere words; {agentA2} smiled through red eyes.',
        '心情大好的{agentA}在{loc}拉著{agentB}分享喜悅，開懷大笑的聲音感染了整個{loc2}，連路過的人都忍不住嘴角上揚。': 'In high spirits, {agentA} grabbed {agentB} at {loc} to share the joy, and their hearty laughter spread across {loc2}, making even passers-by smile.',
        '{agentA}和{agentB}在{loc}感慨起命運的安排，聊起了{scene}的美好，最後被{food}的香氣拉回了現實，氣氛輕鬆溫馨。': '{agentA} and {agentB} mused at {loc} about fate and talked about {scene}, until the aroma of {food} pulled them back to reality in a relaxed, warm mood.',
