        '你捐了 {n} 銀幣給鎮公所：繁榮 +1、全鎮今天心情 +2、聲望 +2': 'You donated {n} silver to the town hall: prosperity +1, town mood +2 today, reputation +2',
        '你捐了 {n} 銀幣給鎮公所：全鎮今天心情 +2、聲望 +2（捐款帶來的繁榮已到上限 +{cap}）': 'You donated {n} silver to the town hall: town mood +2 today, reputation +2 (donation prosperity is capped at +{cap})',
        '捐給鎮公所：繁榮 +1、全鎮今天心情 +2、聲望 +2': 'Donate to the town hall: prosperity +1, town mood +2 today, reputation +2',
