        '鎮公所今天收的捐款夠了，明天再來': 'The town hall has taken enough donations today; come back tomorrow',
        '捐給鎮公所': 'Donate to the town hall',
        '花銀幣讓工匠加班：進度 +20%，每個工程每天一次': 'Pay for overtime: progress +20%, once per project per day',
        '今天捐過': 'Funded today',
        '捐': 'Donate',
        '累計': 'total',
        '今天還可 {n} 次': '{n} left today',
        '明天再來': 'tomorrow',
        '小鎮復興了：連續撐過兩季考驗，搬走的人開始回望這裡': 'The town revived: two trials survived in a row, and those who left are looking back this way',
        '小鎮復興了！連續兩季撐過考驗，街上又熱鬧起來：全鎮士氣 +12、繁榮 +15、聲望 +15': 'The town has revived! Two trials survived in a row and the streets are lively again: morale +12, prosperity +15, reputation +15 for the whole town',
        '小鎮復興': 'Town revived',
        '衰敗中': 'In decline',
        '連續撐過兩季考驗就能復興': 'survive two trials in a row to revive',
        '復興過 {n} 次': 'Revived {n} times',
        '天賦都學完了，之後每升一級隨機一項屬性 +1': 'All perks learned; from now on each level adds +1 to a random attribute',
        '級，天賦都學完了：': ', all perks learned: ',
        '從遠方來到了': ' came from afar to ',
        '把小鎮繁榮推到 {p}，往{town}的路就通了：可以押商隊、互訪、跨鎮戀愛；也可以到城鎮列表自己再建一座': 'Push prosperity to {p} and the road to {town} opens: caravans, visits and cross-town romance. You can also found another town from the town list',
        '還沒有通車的鄰鎮：小鎮繁榮到 {p} 就會修好往{town}的路（目前 {c}），之後可以押商隊、互訪、跨鎮戀愛；也可以到「城鎮列表」自己再建一座。': 'No neighbouring town yet. At prosperity {p} the road to {town} gets repaired (now {c}); then you can run caravans, visit and romance across towns. You can also found another town from the town list.',
        '鄰鎮的存檔不在這台裝置上：到「城鎮列表」打開它，或再建一座城鎮，馬車站就會通車。': 'The neighbouring town\'s save is not on this device: open it from the town list, or found another town, and the coach station opens.',
        '{name}在{town}度過了 {d} 天的歲月': '{name} spent {d} days in {town}',
        '這就是{name}在{town}的故事——': '{name}\'s story in {town}: ',
        '加入了': ' joined ',
        '在這座小鎮找到了屬於自己的幸福': 'Found personal happiness in this town',
        '對話由內建 AI 生成，不用填任何金鑰。按下說服、安慰、談條件之後用你自己的話說，AI 會依對方的個性與心情判定這句話打不打得動他，成功率跟著變。': 'Conversations are generated by the built-in AI, no keys to enter. Press Persuade, Comfort or Bargain, then say it in your own words: the AI judges whether the line lands with that villager\'s personality and mood, and your odds shift with it.',
        '每天有事做': 'Something to do every day',
        '早安卡告訴你昨天的結算與今天的委託；村民會開三天的小故事拜託你；商隊要押、季度考驗要親手撐；季末一頁回顧給你評等和下一季怎麼打的建議。': 'A morning card shows yesterday\'s tally and today\'s requests; villagers open three-day stories that need you; caravans to run, seasonal trials to carry yourself; and a season recap grades you and tells you how to play the next one.',
        '五座城鎮各有五章主線與專屬災難，每章兩條路線。旅人會升級選十種天賦。你可以參選鎮長，也可以只當個看戲的旅人。': 'Five towns, each with a five-chapter main story and its own disaster, two routes per chapter. Your traveller levels up through ten perks. Run for mayor, or just watch the town live.',
        '說書': 'Storyteller',
        '村民更常找你走小故事（三成→五成），走完的獎勵 +25%': 'Villagers start stories with you more often (30%→50%) and finishing one pays +25%',
        '知心': 'Empath',
        '「用你的話說」AI 判定每級 ±12%、每天多 10 次，魅力 +1': '"In your own words" AI verdicts swing ±12% per step and allow 10 more a day; charm +1',
        '第 {d} 天': 'Day {d}',
        '早安': 'Good morning',
        '第 5 天公布本季考驗': 'The season trial is announced on day 5',
