        '{npc} 說有封舊信落在{loc}，幫他找回來': '{npc} says an old letter was left at {loc}; fetch it back',
        '{npc} 想找個人陪他把那封信讀完': '{npc} wants company while reading that letter to the end',
        '{npc} 要做件像樣的衣服去見寫信的人，缺 {n} 布料': '{npc} wants a proper outfit to meet the letter writer and is short {n} cloth',
        '{npc} 穿著新衣出門了，回來時眼睛紅紅的，說「謝謝你陪我走這一趟」': '{npc} left in the new clothes and came back red-eyed: "thank you for walking this with me"',
        '漏水的屋頂': 'The leaking roof',
        '{npc} 家的屋頂漏了，先要 {n} 木材撐著': '{npc}\'s roof is leaking; {n} wood to shore it up first',
        '{npc} 說{loc}有合用的石片，去搬一趟': '{npc} says {loc} has the right stone slabs; go haul some',
        '屋頂修好了，{npc} 想請你坐坐，喝杯熱的': 'The roof is fixed; {npc} wants you over for something hot',
        '{npc} 家不漏了；他說以後下雨天都會想起你': '{npc}\'s house is dry now; they say every rainy day will remind them of you',
        '偷偷準備的生日': 'A secret birthday',
        '{npc} 想偷偷替人準備生日，要你去{loc}拿東西': '{npc} is secretly planning a birthday and needs you to pick something up at {loc}',
        '{npc} 要辦一桌，缺 {n} 食物': '{npc} is laying a table and is short {n} food',
        '壽星的禮物還沒著落，{npc} 請你送份心意': 'The birthday gift is still missing; {npc} asks you to bring one',
        '生日宴上大家都笑了，{npc} 說這是今年最好的一天': 'Everyone laughed at the party; {npc} called it the best day this year',
        '放不下的心結': 'A grudge that will not let go',
        '{npc} 嘴硬不問，卻想知道 {target} 最近過得怎樣（去跟他「打聽」）': '{npc} will not ask, but wants to know how {target} is doing (go "Ask around")',
        '{npc} 鬆口了，願意讓你在中間說和': '{npc} relented and will let you mediate',
