        '明天的委託板會多一件他的事，連做三天': 'Tomorrow\'s board will carry their request, three days in a row',
        '走完 {n} 段村民的小故事': 'Saw {n} villager stories through',
        '下一季怎麼打': 'How to play next season',
        '糧荒靠親手帶進食物：每天跟一兩位務農或廚子「求助」，或到田裡收成、向商人買進': 'Famine is about food you bring in yourself: ask a farmer or cook for help every day, harvest your fields or buy from merchants',
        '瘟疫找醫生、學者、牧師「求助」，藥品一份算三份；委託報酬的草藥也算': 'For plague ask the doctor, researcher or priest for help; medicine counts three; herbs from request rewards count too',
        '匪患要蓋防禦：訓練場（木 20、石 10、工具 2）或瞭望塔，蓋到一半也按進度計': 'Bandits need defences: a training ground (wood 20, stone 10, tools 2) or watchtower; half-built counts by progress',
        '商會壓價靠自己賺：多押幾趟商隊、交付委託拿銀幣、把多的貨賣掉': 'A price war is about silver you earn yourself: run more caravans, deliver requests, sell surplus goods',
        '每季第 5 天公布考驗，前四天先囤好感和物資，公布後再對症下手': 'The trial is announced on day 5; stock up affinity and goods for four days, then act on what it asks',
        '委託先挑一次對話就能完成的（陪伴、送禮），同一天第一件過期扣 3 好感、其餘每件扣 1': 'Pick requests one chat can finish (company, gifts); the first expiry of a day costs 3 affinity, the rest 1 each',
        '到馬車站押一趟商隊試試：30 份木材走大路，風險約一成、賣價多兩成': 'Try a caravan from the coach station: 30 wood by road, about 10% risk, 20% better price',
        '每天用「用你的話說」跟一位村民聊，說到他在乎的事成功率 +16%，好感跟著漲': 'Talk to one villager a day in your own words; hitting what they care about adds 16% odds and affinity follows',
        '人口在流失：撐過考驗，心情低的人多去「安慰」，有空房就留得住人': 'Population is draining: survive the trial, comfort the low-mood villagers, keep a spare house free',
        '經驗來自委託、考驗、商隊和主線任務；推進一章主線的經驗最多': 'XP comes from requests, trials, caravans and the main quest; a main-quest chapter gives the most',
        '這季打得不錯：下一季試著連續全清委託板，連清兩天每天會多一件': 'A good season: next time try clearing the whole board on consecutive days; two in a row adds a request a day',
