        '每天要做的事': 'Things to do every day',
        '這不只是看戲——<strong>每天都有事要排</strong>：': 'This is not just a show to watch: <strong>there is something to plan every day</strong>:',
        '📋 委託板 —— 村民每天早上發 3–5 件委託，行動點只有 5 點，挑著做；沒做完的會過期': '📋 Request board — villagers post 3–5 requests each morning; you have 5 action points, so pick; unfinished ones expire',
        '🐪 押商隊 —— 在馬車站選貨、選鎮、要不要派護衛；可能賺四成，也可能遇劫': '🐪 Caravans — pick goods, a town and an escort at the coach station; up to +40%, or a raid',
        '⚖️ 季度考驗 —— 每季第 5 天公布，季末結算；撐過有永久加成，沒撐過會有人搬走': '⚖️ Seasonal trials — announced on day 5, settled at season end; survive for a permanent perk, fail and people leave',
        '🎲 每句話都有成功率 —— 聊天的意圖鈕會顯示 %，看對方性格和你的交情': '🎲 Every line has odds — chat intent buttons show a %, based on their personality and your standing',
        '🧭 旅人會升級 —— 完成委託、撐過考驗、押商隊都給經驗，每級選一個天賦': '🧭 The traveller levels up — requests, trials and caravans give XP; pick a perk every level',
        '這些都在「故事」分頁的最上方；每天早上也會有通知提醒你。': 'All of this sits at the top of the Story tab, and a morning notice reminds you.',
