        '每天有委託要排、商隊要押、季度考驗要撐；五座城鎮各有五章主線與專屬災難，每章兩條路線。旅人會升級選天賦，每句話都有成功率。你可以參選鎮長，也可以只當個看戲的旅人。': 'Every day there are requests to plan, caravans to send and a seasonal trial to survive; each of the five towns has a five-chapter story and a signature disaster, two routes per chapter. The traveller levels up and picks perks, and every line you say has odds. Run for mayor, or just stay a traveller watching the show.',
