        ' 次': ' more',
        '完成委託、撐過考驗、押商隊、推進故事都會累積經驗；每升一級選一個天賦。': 'Requests, trials, caravans and story progress all earn XP; pick a perk at every level.',
        '級': '',
        '到「故事」分頁選一個天賦': 'Pick a perk in the Story tab',
        '委託板、押商隊、季度考驗已上線，旅人成長接續': 'Request board, player caravans and seasonal trials are live; traveller growth follows',
        '衰敗結局': 'Decline Ending',
        '連續兩季撐不住，人走了一半': 'Two seasons lost; half the town has left',
        '接連兩季的考驗沒有撐過去。糧倉見底、街上冷清，一戶戶人家搬去了別的鎮。留下來的人還在，爐火還沒熄——這座鎮是否能再站起來，要看你接下來怎麼做。': 'Two seasonal trials in a row were lost. The granary is empty, the streets are quiet, and family after family has moved to other towns. Those who stayed are still here and the hearth is not out yet. Whether this town rises again depends on what you do next.',
        '那個路過的旅人不太尋常……他來過之後，鎮上總會發生怪事。': 'That wandering traveler isn\'t ordinary... strange things keep happening after each visit.',
        '🕯️ {a}開始覺得那個旅人不是普通人。': '🕯️ {a} is starting to think the traveler is no ordinary person.',
        '我相信那個旅人是神明化身，只是不能說破。': 'I believe the traveler is a god in disguise. I just can\'t say it out loud.',
        '🙏 {a}私下相信那個旅人是神明化身。': '🙏 {a} secretly believes the traveler is a god in disguise.',
        '{a}悄悄跟我說，那個路過的旅人可能是神明。': '{a} whispered to me that the wandering traveler might be a god.',
        '路過的旅人跟我說：「{m}」': 'The wandering traveler told me: "{m}"',
        '{a}說那個路過的旅人跟他講過：「{m}」': '{a} says the wandering traveler told them: "{m}"',
        '路過的旅人跟你說過的話': 'What the wandering traveler told you',
        '他是個時常路過小鎮的旅人，來去無蹤，不住在鎮上、也沒有官職，沒人知道他從哪裡來，用名字叫他就好。他說的話你會放在心上，但你有自己的判斷，不會照單全收。': 'They are a traveler who often passes through town, coming and going without a trace. They don\'t live here and hold no office, and nobody knows where they come from; just call them by name. You take what they say to heart, but you have your own judgment and won\'t accept everything they say.',
        '你隱約覺得他不是普通人：他來過之後，鎮上總會發生怪事。你對他有點好奇、有點敬畏，但不確定。': 'You have a vague feeling they are no ordinary person: strange things always happen in town after they visit. You\'re curious and a little in awe, but not sure.',
        '你私下相信他是神明化身，對他又敬又畏，說話會小心，也許會想求他保佑；但你不會當眾說破。': 'You secretly believe they are a god in disguise. You revere and fear them, choose your words carefully, and might ask for their blessing, but you would never say it in public.',
        '相信旅人是神明': 'Believes the traveler is a god',
        '懷疑旅人不是凡人': 'Suspects the traveler is not mortal',
