        '{f}拿{c}的把柄勒索了 {n} 銀幣': '{f} blackmailed {c} for {n} silver',
        '{f}拿我的把柄勒索我。': '{f} is blackmailing me with what they know.',
        '💰 {f}私下拿{c}的把柄勒索。🕵️「{why}」': '💰 {f} is quietly blackmailing {c}. 🕵️ "{why}"',
        '📢 {f}決定公開{c}的事：「{why}」': '📢 {f} decided to go public about {c}: "{why}"',
        '人都會犯錯，我不想記恨。': 'Everyone makes mistakes. I do not want to hold a grudge.',
        '他是真心的，我就給他一次機會。': 'They meant it, so I will give them a chance.',
        '這種事哪是一句對不起就算了？': 'Do they think one sorry is enough for that?',
        '我需要一點時間。': 'I need some time.',
