        '還不肯原諒': ' will not yet forgive ',
        '以下每一對村民，道歉之後一方原諒或不原諒。請用被道歉的人的口吻各寫一句理由（20 字內）。只輸出 JSON 陣列': 'For each pair of villagers below, after an apology one forgave or did not. In the voice of the one apologized to, write one reason each (under 12 words). Output only a JSON array',
