        '🙏 {a}的禱詞：「{x}」': '🙏 {a}\'s prayer: "{x}"',
        '我夢見有個聲音對我說：「{x}」': 'I dreamed a voice said to me: "{x}"',
        '）。昨晚你夢見有個聲音對你說': '). Last night you dreamed a voice told you',
        '。依你的個性與處境，你怎麼解讀？可能誤會。用第一人稱一句話說你的解讀，並選一個行動類型：build、reconcile、journey、love、wealth、warning、vague。只輸出 JSON': '. Given your personality and situation, how do you interpret it? You may misunderstand. Give your reading in one first-person sentence and pick an action type: build, reconcile, journey, love, wealth, warning or vague. Output only JSON',
        '🌙 {a}醒來，想起昨晚的夢：「{x}」': '🌙 {a} woke up remembering last night\'s dream: "{x}"',
