        '📖 {a}把夢裡的話寫進{r}的教誨。': '📖 {a} wrote the words from the dream into the teachings of the {r}.',
        '🕊️ {a}受夢啟發，主動去找{b}和好。': '🕊️ Inspired by the dream, {a} went to make peace with {b}.',
        '夢裡的啟示': 'A revelation from a dream',
