        '💰 銀行家{a}掏出自己的 {n} 銀幣補進銀行，想穩住人心。': '💰 Banker {a} put {n} silver of their own into the bank to calm everyone down.',
        '擠兌的時候我把自己的 {n} 銀幣都押進銀行了，不能讓它倒。': 'During the bank run I put {n} silver of my own into the bank. I can\'t let it fall.',
        '📜 銀行家{a}發行債券：三十天到期，利息 {r}%{why}。': '📜 Banker {a} issued bonds: due in 30 days, {r}% interest{why}.',
