        '我買了 {n} 銀幣的銀行債券，三十天後連本帶利拿回來。': 'I bought {n} silver of bank bonds. In 30 days I get it back with interest.',
        '📜 {k} 個人買了債券，銀行籌到 {n} 銀幣。': '📜 {k} people bought bonds; the bank raised {n} silver.',
        '📜 沒有人敢買銀行的債券。': '📜 Nobody dared to buy the bank\'s bonds.',
        '我發行債券籌到了 {n} 銀幣。': 'I raised {n} silver by issuing bonds.',
        '我發行債券，結果沒有人買。': 'I issued bonds, but nobody bought any.',
        '銀行債券到期，連本帶利拿回 {n} 銀幣。': 'My bank bond came due and I got back {n} silver with interest.',
        '📉 銀行付不出{a}的債券，只還了 {p}／{n} 銀幣。': '📉 The bank couldn\'t pay {a}\'s bond in full: only {p} of {n} silver.',
        '銀行債券到期只拿回 {p} 銀幣，說好的 {n} 呢？': 'My bank bond came due and I only got {p} silver back. What happened to the {n} I was promised?',
        '存錢的人太多，銀行倒了全鎮都要遭殃': 'Too many people have savings there; if the bank falls, the whole town suffers',
        '銀行倒了，鎮上的生意也會跟著垮': 'If the bank falls, the town\'s businesses go down with it',
        '鎮公所已經欠了一屁股債，不能再借了': 'The town hall is already deep in debt; we can\'t borrow more',
        '銀行家自己闖的禍，自己收拾': 'The banker made this mess; the banker can clean it up',
        '公庫不該替銀行的錯誤買單': 'The treasury shouldn\'t pay for the bank\'s mistakes',
        '🏦 銀行暫停營業一天，等{m}決定要不要紓困。': '🏦 The bank closed its doors for a day while {m} decides whether to bail it out.',
        '你正在扮演': 'You are playing ',
        '銀行正在擠兌': 'There is a run on the bank',
        '存戶': 'depositors',
