        '有人笑了，就有人睡不著。': 'When someone smiles, someone else loses sleep.',
        '這座小鎮的秘密，才剛開始。': 'This town\'s secrets are only beginning.',
        '提案 {id}（{title}）還在等表決，明天會過嗎？': 'Proposal {id} ({title}) is still awaiting a decision. Will it pass tomorrow?',
        '選舉正打得火熱，誰會坐上鎮長的位子？': 'The election is heating up. Who will become mayor?',
