        '提案 {id}（{title}）還在等表決。': 'Proposal {id} ({title}) is still awaiting a decision.',
        '鎮長選舉進行中。': 'The mayoral election is under way.',
        '{name}還沒過去。': '{name} isn\'t over yet.',
        '現任{title}': 'Current {title}',
        '從缺': 'Vacant',
        '出去探險': 'away exploring',
        '出遠門': 'away traveling',
        '代理': ' acting',
        '所有玩家都用小鎮內建的 AI：先用 Claude，Claude 不能用才換 GPT，兩個都不能用才用 Groq 備援。每個帳號每天有使用上限；金鑰只放在伺服器，網頁原始碼和存檔裡都沒有。': 'Every player uses the built-in AI: Claude first, GPT only if Claude is unavailable, and Groq as a backup only if both are down. Each account has a daily limit; the keys live only on the server, never in the page source or saves.',
        '對話、行程、反思、投票與鎮長裁決一律先問 Claude，品質一致；Claude 不能用才換 GPT，兩個都不能用才用 Groq 備援。': 'Conversations, schedules, reflections, votes and mayoral rulings always go to Claude first for consistent quality; GPT is used only if Claude is unavailable, and Groq only if both are down.',
        'AI 金鑰全部放在伺服器環境變數，網頁原始碼與存檔裡都沒有；玩家不需要、也不能填自己的金鑰。': 'All AI keys live in server environment variables, never in the page source or saves; players don\'t need, and can\'t enter, their own key.',
        '張事件卡': 'event cards',
        '項研究': 'research nodes',
        '種建築': 'buildings',
        '級城鎮': 'town tiers',
        '種宗教骨架': 'religion archetypes',
        '條記憶／每人': 'memories per villager',
        '例：開新遊戲 → 新的邊境鎮、新的鄰居、新的地圖': 'e.g. New game → a new Frontier Town, new neighbors, a new map',
        '點村民，鏡頭就跟著他，看得到他在想什麼、跟誰要好、欠誰錢。提案頁看大家想做什麼，觀察者日報看昨天發生了什麼。': 'Click a villager and the camera follows them: see what they\'re thinking, who they\'re close to and who they owe money. The Proposals tab shows what people want; The Observer Daily shows what happened yesterday.',
        '例：點鐵匠 → 看到他暗戀麵包師、還欠酒館三天的帳': 'e.g. Click the blacksmith → he has a crush on the baker and owes the tavern three days of tabs',
        '例：打出「旱災」→ 農夫提案開水圳 → 全鎮投票': 'e.g. Play "Drought" → a farmer proposes an irrigation channel → the town votes',
        '例：七天後糧價回穩，提案的農夫在下次選舉多拿了票': 'e.g. Seven days later food prices settle, and that farmer gains votes at the next election',
        '天亮開工': 'Work at dawn',
        '農夫依地形去種田、捕魚或打獵，鐵匠打工具，木匠造紙做家具。': 'Farmers farm, fish or hunt depending on the terrain; blacksmiths forge tools; carpenters make paper and furniture.',
        '提案與投票': 'Proposals and votes',
        '有人提議蓋穀倉、有人想調稅率；全鎮投票，村長拍板並說出理由。': 'Someone wants a granary, someone wants a tax change; the town votes and the chief decides, giving reasons.',
        '酒館八卦': 'Tavern gossip',
        '午飯時間最熱鬧：誰暗戀誰、誰欠錢不還，消息一傳十、十傳百，越傳越走樣。': 'Lunch is the busiest hour: who has a crush on whom, who won\'t pay back a loan; news spreads and gets more twisted with every retelling.',
        '商隊進城': 'Caravans arrive',
        '海港帶來魚和鹽、林間村帶來木材和紙，缺什麼就靠貿易補。': 'Harbors bring fish and salt, forest villages bring wood and paper; whatever is missing comes by trade.',
        '約會與吵架': 'Dates and quarrels',
        '有人在廣場告白，有人當眾對嗆；派系在角落密謀下一次選舉。': 'Someone confesses in the square, someone picks a public fight; factions plot the next election in a corner.',
        '一天的八卦與大小事整理成一份報紙，隔天早上讀。': 'The day\'s gossip and events are compiled into a paper to read the next morning.',
        '記憶與反思': 'Memory and reflection',
        '戀愛與婚姻': 'Love and marriage',
        '謊言與陰謀': 'Lies and schemes',
        '選舉與議會': 'Elections and councils',
        '國王與政變': 'Kings and coups',
        '地形決定物產': 'Terrain shapes produce',
        '商隊貿易': 'Caravan trade',
