        '手機可玩': 'Plays on phones',
        '每天的八卦與大小事整理成一份報紙，可以翻前幾期。': 'Each day\'s gossip and events become one paper; flip back through earlier issues.',
        '村民自己提案，票數、投票理由和村長裁決都看得到。': 'Villagers write their own proposals; you can see the vote counts, the reasons and the chief\'s ruling.',
        '村民資訊卡': 'Villager card',
        '點一下就知道他在做什麼、為什麼、心裡在想什麼。': 'One click shows what they\'re doing, why, and what\'s on their mind.',
        '這座鎮擅長產什麼、缺什麼、要靠商隊買什麼。': 'What this town is good at producing, what it lacks and what it must buy by caravan.',
        '村長＋長老會 3 席': 'Chief + 3-seat Council of Elders',
        '一切的開始：二十幾個人、一間鎮公所。': 'Where it all starts: two dozen people and one town hall.',
        '人口 30＋繁榮 50＋第一時代': 'Pop 30 + prosperity 50 + era 1',
        '鎮長與 5 席鎮議會，銀行與報社陸續出現。': 'A mayor and a 5-seat council; banks and newspapers appear.',
        '人口 60＋繁榮 65＋第二時代': 'Pop 60 + prosperity 65 + era 2',
        '市長與 7 席市議會，石板路、旗幟、更多移民。': 'A lord mayor and a 7-seat council, paved streets, banners and more immigrants.',
        '人口 100＋繁榮 80＋第三時代': 'Pop 100 + prosperity 80 + era 3',
        '國王加冕、王令與政變，9 席王都議會。': 'A crowned king, royal decrees and coups, and a 9-seat assembly.',
        '要下載或安裝嗎？': 'Do I need to download or install anything?',
        '不用。打開網頁就能玩，電腦、平板、手機都可以。': 'No. It runs in the browser on computers, tablets and phones.',
        '我可以控制村民嗎？': 'Can I control the villagers?',
        '不行，這是觀察型遊戲。你能做的是打事件卡、託夢、化身旅人聊天，其他全由村民自己決定。': 'No, it\'s an observation game. You can play event cards, send dreams and chat as a traveler; the villagers decide everything else.',
        '存檔會不會不見？': 'Could I lose my save?',
        '登入後存檔會自動同步到雲端，換裝置登入就能接著玩；本機也會留一份備份。': 'Once logged in, saves sync to the cloud automatically so you can continue on another device; a local backup is kept too.',
        '為什麼要邀請碼？': 'Why is an invite code needed?',
        '小鎮的 AI 由伺服器負擔，目前用邀請制控制人數。': 'The town\'s AI runs on our servers, so sign-ups are invite-only for now.',
        'AI 會不會亂講話？': 'Will the AI say random things?',
        '村民只能根據自己的記憶、性格和鎮上真的發生的事說話；伺服器也會擋掉不像村民的回覆。': 'Villagers speak only from their own memories, personality and what really happened in town; the server also blocks replies that don\'t sound like a villager.',
        '有英文版嗎？': 'Is there an English version?',
        '有。右上角切換中文／English，村民對話、日報、介面都會換。': 'Yes. Switch 中文 / English at the top right; villager dialogue, the daily paper and the interface all change.',
