        '皺著眉頭把你拉到一旁：「': ' pulls you aside with a frown: "',
        '鎮上的人都慌了，你說該怎麼辦？」': 'Everyone\'s panicking — what should we do?"',
        '深夜還亮著燈,見你經過連忙招手：「': '\'s lamp is still lit late at night; they wave you over: "',
        '我想聽聽你的看法,再晚就來不及了。」': 'I need your take — soon it\'ll be too late."',
        '在廣場上攔住你,壓低聲音：「': ' stops you in the square, voice low: "',
