        '和解進度': 'Reconciliation progress',
        '他還不信任你——先提升關係再來調解': 'They don\'t trust you yet — build the relationship first, then mediate',
        '（心防鬆動了）': ' (their guard is coming down)',
        '昨晚忙完': 'Last night after finishing my ',
        '的事,躺下來滿腦子都是你。這樣下去不行,我得說出來——我喜歡你。': ' work, I lay down and could only think of you. I have to say it — I like you.',
        '鎮上的人都說我最近怪怪的。也對,遇見你之後,我就不太像原本的自己了。': 'Everyone says I\'ve been acting strange lately. They\'re right — since meeting you, I\'m not quite my old self.',
        '我練習了好多次要怎麼開口...結果一看到你全忘了。總之,我心裡有你,很久了。': 'I rehearsed this so many times... then forgot it all when I saw you. Anyway — you\'ve been in my heart for a long time.',
        '如果哪天你要離開這個鎮,能不能...帶上我?': 'If you ever leave this town... would you take me with you?',
        '做': 'Doing ',
        '這行,平常沒什麼人真的關心我。你不一樣。這句話我想當面說。': ' work, few people ever really care about me. You\'re different. I wanted to say that to your face.',
        '昨天想了想,要是你當初沒來這個鎮,我大概還是一個人悶著。謝了,真的。': 'I was thinking — if you\'d never come to this town, I\'d probably still be keeping to myself. Thanks. Really.',
        '別笑我肉麻——在這鎮上,我最信得過的人就是你。': 'Don\'t laugh — of everyone in this town, you\'re the one I trust most.',
        '我這人朋友不多,但質都很高。比如說,你。': 'I don\'t have many friends, but the ones I have are top quality. You, for instance.',
        '那個...': 'Um... ',
