        '促成一對絕交的村民世紀大和解': 'Broker a grand reconciliation between two estranged villagers',
        '積怨徹底爆發,當眾撂下重話,正式絕交!': ' — their grudge finally exploded; harsh words in public, officially estranged!',
        '在眾目睽睽下大吵一架,火藥味十足!': ' had a blazing public row — sparks flying!',
        '當眾對嗆,鎮上議論紛紛': ' clashed in public; the town is abuzz',
        '公開絕交,兩人再不相往來': ' publicly cut ties — they want nothing to do with each other',
        '徹底鬧翻,絕交了。這口氣嚥不下去。': ' and I are completely done. I can\'t swallow this.',
