        '成了!': 'It worked! ',
        '當眾和解!': ' publicly reconciled!',
        '兩人好感 +8 · 聲望 +15': 'Both +8 affinity · Reputation +15',
        '沉默許久:「...讓我想想。」': ' falls silent for a long while: "...Let me think."',
        '再去勸勸': 'Now go persuade ',
        ',兩邊都點頭就能促成和解': ' — when both sides agree, the reconciliation happens',
        '經你居中調解,': 'Thanks to your mediation, ',
        '鬧到絕交了——分別找兩人用「調解」勸和': ' are estranged — talk to each of them with "Mediate"',
        '和解只差一步!再去用「調解」勸勸': 'One step from peace! Use "Mediate" on ',
        '促成世紀大和解:兩人好感大增、聲望 +15、成就「和事佬」': 'Broker the grand reconciliation: big affinity gains, +15 reputation, "Peacemaker" achievement',
        '喲,這不是最會做表面功夫的那位嗎?': 'Well well, if it isn\'t the master of keeping up appearances?',
        '總比某些人背後嚼舌根來得光明磊落。': 'Better than gossiping behind backs like some people.',
        '你再說一次試試看?大家都在,正好評評理!': 'Say that again! Everyone\'s here — let them judge!',
        '評就評!我還怕你不成?': 'Fine by me! You think I\'m scared of you?',
        '夠了。這些年我忍你很久了。': 'Enough. I\'ve put up with you for years.',
        '忍?說得好像只有你在忍一樣。': 'Put up with ME? As if you were the only one suffering.',
        '那正好。從今天起,你走你的路,我過我的橋。': 'Perfect. From today on, you go your way, I go mine.',
