        '彼此彼此。其實...當年那件事,我也有不對。': 'Same to you. Honestly... I was in the wrong back then too.',
        '都過去了。有人苦口婆心勸了我好幾回,我才想通——為那點事賭一輩子的氣,不值得。': 'It\'s all in the past. Someone kept urging me until I realized — a lifetime of grudges isn\'t worth it.',
        '嗯。回頭請那位和事佬喝一杯吧,算我們倆的。': 'Yeah. Let\'s buy that peacemaker a drink — on both of us.',
        '有些人真的很會踩人底線。不點名。': 'Some people really know how to cross the line. No names.',
        '今天話說重了?不,我只後悔沒早點說。': 'Too harsh today? No — I only regret not saying it sooner.',
        '道不同不相為謀。就到這裡吧。': 'We were never on the same path. This is where it ends.',
        '刪掉了一個人。心裡反而輕鬆了。': 'Cut someone off. Honestly, I feel lighter.',
        '冰釋前嫌的感覺,真好。🕊️': 'Burying the hatchet feels good. 🕊️',
        '謝謝那位替我們兩個奔走的人。改天請你喝一杯!': 'Thanks to the one who ran back and forth for us. Drinks on me sometime!',
        '這對積怨已久的死對頭在大庭廣眾下狹路相逢,當場吵了起來,句句帶刺誰也不讓誰,圍觀的鎮民議論紛紛': ' — sworn rivals crossing paths in public, trading barbs, neither backing down as the town watches',
