        '研究完成會帶來新觀念，靠村民聊天傳開；個性、年紀、職業和鎮上民風決定誰接受、誰反對。立場會影響競選政見，被新工坊搶了飯碗的匠人可能提案抗議。': 'Each finished research brings a new idea that spreads as villagers chat; personality, age, job and the town’s temperament decide who accepts it and who opposes it. Stances shape election platforms, and craftspeople whose work is taken by a new workshop may propose a protest.',
