        '地標': 'Landmarks',
        '照提案執行': 'Carried out as proposed',
        '本鎮的規矩與地標': 'Town customs and landmarks',
        '你想向全鎮提一個你自己想出來的提案。可以很實際，也可以天馬行空、有個人色彩（例如替廣場的貓立雕像、每週一天大家只能說真話、讓鐵匠去學醫），但要符合你的個性、記憶和鎮上現況。': 'You want to put a proposal of your own to the whole town. It can be practical or wildly imaginative and personal (for example a statue for the cat in the square, one day a week when everyone must tell the truth, or sending the blacksmith to train as a doctor), but it must fit your personality, memories and the state of the town.',
