        '【能蓋的建築】': '[Buildings you can build] ',
        '【能研究的】': '[Research available] ',
        '提案的效果只能用下面幾種（effects 陣列，最多 4 個；好處要有代價，太划算會被打折）：': 'Effects may only use the types below (effects array, at most 4; benefits must have a cost, and deals that are too good will be scaled down):',
