        // v6.48.0 事件卡獨立介面
        '事件卡：今天還能打 {n} 張（E）': 'Event cards: {n} left today (E)',
        '手牌': 'Hand',
        '還沒打過事件卡。打出一張，村民接下來幾天的反應、提案和七天後的變化都會記在這裡。': 'No event cards played yet. Play one and the villagers’ reactions over the next few days, their proposals and the changes seven days later will be recorded here.',
        '隨機打一張': 'Play a random card',
        '打出後鏡頭會帶到現場；村民接下來幾天的反應會出現在「反應追蹤」。': 'Playing it takes the camera to the scene; villagers’ reactions over the next few days appear under Reaction log.',
        '事件卡搬到地圖右下角的 🃏 按鈕了（桌機按 E）。': 'Event cards have moved to the 🃏 button at the bottom right of the map (press E on desktop).',
        '打開事件卡': 'Open event cards',
        '事件卡是什麼？': 'What are event cards?',
        '你不在鎮上，只在天上看著村民過日子。事件卡是你唯一能「動手」的地方：打出一張，就讓一件事發生在鎮上，然後看村民怎麼反應。': 'You are not in the town; you watch the villagers live their lives from above. Event cards are the only way you can step in: play one and something happens in town, then watch how the villagers react.',
        '天災、🕳️ 人禍、🍀 機運、💞 人際四類；每張卡下方寫著會發生什麼': 'Disasters, 🕳️ mishaps, 🍀 fortune and 💞 people: four kinds, and each card says what will happen',
        '每天最多打 {n} 張，打過的卡要冷卻幾天才能再用': 'Play up to {n} cards a day; a card you have played needs a few days to cool down before you can use it again',
        '村民會聊這件事、記在心裡、跟著提出提案；「反應追蹤」會記下他們的反應和七天後的變化': 'Villagers talk about it, remember it and may make proposals about it; "Reaction log" records what they did and how things changed seven days later',
        '知道了，看手牌': 'Got it, show my cards',
        '【鎮上眼前的狀況與大家在談的事（越前面越急；可以照著提、改成你的版本，也可以都不管、提你自己的點子）】': '[What is going on in town and what people are talking about (most urgent first; you can propose one as is, make your own version, or ignore them all and propose your own idea)]',
