        '「{x}」總算過去了，鬆了一口氣。': '"{x}" is finally over. What a relief.',
        '存糧不夠，這幾天只能吃半飽，肚子一直餓。': 'There isn\'t enough food. I have only eaten half my fill these past days and I\'m always hungry.',
        '鎮上沒東西吃': 'there was nothing to eat in town',
